import 'package:riverpod_annotation/riverpod_annotation.dart';
import 'package:cleanclik/core/services/business/inventory_service.dart';

// Re-export so consumers importing this file get the real
// inventoryServiceProvider (generated by the @riverpod InventoryService class).
export 'package:cleanclik/core/services/business/inventory_service.dart';

part 'inventory_provider.g.dart';

// NOTE: inventoryServiceProvider is generated from the @riverpod class
// InventoryService in inventory_service.dart. Do not declare an alias
// function provider here — its generated name collides and shadows the real
// provider, making it watch itself ("A provider cannot depend on itself").

/// Provider for current inventory items
/// Requirements: 2.1, 3.1
@riverpod
List<InventoryItem> inventoryItems(InventoryItemsRef ref) {
  final service = ref.watch(inventoryServiceProvider);
  return service.inventory;
}

/// Provider for inventory items by category
/// Requirements: 2.1, 3.1
@riverpod
List<InventoryItem> inventoryItemsByCategory(
  InventoryItemsByCategoryRef ref,
  String category,
) {
  final service = ref.watch(inventoryServiceProvider);
  return service.getItemsByCategory(category);
}

/// Provider for inventory empty state
/// Requirements: 2.1, 3.1
@riverpod
bool isInventoryEmpty(IsInventoryEmptyRef ref) {
  final service = ref.watch(inventoryServiceProvider);
  return service.isEmpty;
}
